SELECT bs."in.state" AS state, bs."in.county_name" AS county_name, sum(1) AS metadata_rows_count, count(distinct(bs.bldg_id)) AS model_count, sum(bs.weight) AS units_count, sum(bs."out.electricity.total.energy_consumption" * bs.weight) AS "electricity.total.energy_consumption__baseline", sum(up."out.electricity.total.energy_consumption" * bs.weight) AS "electricity.total.energy_consumption__upgrade", sum((coalesce(bs."out.electricity.total.energy_consumption", 0) - coalesce(up."out.electricity.total.energy_consumption", 0)) * bs.weight) AS "electricity.total.energy_consumption__savings" FROM resstock_2024_amy2018_release_2_metadata AS bs JOIN resstock_2024_amy2018_release_2_metadata AS up ON bs.bldg_id = up.bldg_id AND bs.upgrade = 0 AND up.upgrade = 1 AND up.applicability = true WHERE bs.applicability = true AND bs.upgrade = 0 AND bs."in.state" IN ('CO', 'WY') AND bs.bldg_id IN (13, 16, 33, 128, 182, 196, 244, 245, 282, 302, 376, 407, 430, 431, 449, 552) GROUP BY 1, 2 ORDER BY 1, 2